// Generated by Node crypto.scryptSync using the hexadecimal salt as a string.
const qxchatTestPassword = "QXChat-password-123"
const qxchatTestSalt = "00112233445566778899aabbccddeeff"
const qxchatTestLegacyHash = qxchatTestSalt + ":db8f92b53d92279c5fe4bc945ce45f5e06593baebcded85b1d0df5250004abf8392e0591f0b4ffec611cfbbd8d1a13f4298a0d200016859d5cb6de59374ffe3c"
const qxchatTestCurrentHash = "scrypt$v1$131072$8$1$" + qxchatTestSalt + "$5f89ab15b5c5cc24e139c1c25842d69b231decb8e0046dbd1499927988d17b87608e979ce523cd88dfb5ac32b2c905b463d6c68b54149865cbb6513e436c645e"
const qxchatTestSource = "11111111-2222-4333-8444-555555555555"
const qxchatTestRequest = "66666666-7777-4888-9999-aaaaaaaaaaaa"
const qxchatTestSecret = "qxchat-identity-isolated-test-secret-123456"

func qxchatTestProfile() model.QXChatSourceProfile {
	return model.QXChatSourceProfile{RequestID: qxchatTestRequest, SourceID: qxchatTestSource, Username: "legacy-user", Email: "legacy@example.com", DisplayName: "Legacy user",
		PasswordHash: qxchatTestLegacyHash, CredentialVersion: strings.Repeat("a", 64), Authority: "qxchat", Eligible: true, EmailVerified: true}
}

func setupQXChatIdentityTest(t *testing.T) (*model.User, service.AuthIdentity) {
	t.Helper()
	user, identity := setupSecurityEnrollmentTest(t)
	for range 2 { require.NoError(t, model.MigrateQXChatIdentity(model.DB)) }
	var preserved model.User
	require.NoError(t, model.DB.First(&preserved, user.Id).Error)
	assert.Equal(t, user.Password, preserved.Password)
	assert.Equal(t, user.Status, preserved.Status)
	return user, identity
}

type qxchatSourceFixture struct {
	mu sync.Mutex
	profile model.QXChatSourceProfile
	committed *service.QXChatCommitRequest
	prepareCalls, commitCalls int
	loseReceipt, tamperResponse, refuseCommit bool
	nonces map[string]bool
}

func startQXChatSourceFixture(t *testing.T) *qxchatSourceFixture {
	t.Helper()
	fixture := &qxchatSourceFixture{profile: qxchatTestProfile(), nonces: make(map[string]bool)}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fixture.mu.Lock()
		defer fixture.mu.Unlock()
		body, err := io.ReadAll(r.Body)
		if !assert.NoError(t, err) { w.WriteHeader(http.StatusInternalServerError); return }
		digest := sha256.Sum256(body)
		nonce := r.Header.Get("X-QXChat-Nonce")
		canonical := strings.Join([]string{"qxchat-identity-v1", "POST", r.URL.Path, r.Header.Get("X-QXChat-Timestamp"), nonce, hex.EncodeToString(digest[:])}, "\n")
		if !assert.Equal(t, common.GenerateHMACWithKey([]byte(qxchatTestSecret), canonical), r.Header.Get("X-QXChat-Signature")) || !assert.False(t, fixture.nonces[nonce]) {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}
		fixture.nonces[nonce] = true
		status := http.StatusOK
		var result any
		switch r.URL.Path {
		case "/api/account-unification/prepare":
			fixture.prepareCalls++
			var input struct { RequestID, Identifier, Password string }
			var request map[string]string
			if common.Unmarshal(body, &request) != nil { w.WriteHeader(http.StatusBadRequest); return }
			input.RequestID, input.Identifier, input.Password = request["request_id"], request["identifier"], request["password"]
			if input.Password != qxchatTestPassword || fixture.committed != nil {
				status, result = http.StatusUnauthorized, map[string]string{"error": "credentials"}
			} else {
				profile := fixture.profile
				profile.RequestID = input.RequestID
				result = profile
			}
		case "/api/account-unification/commit":
			fixture.commitCalls++
			var input service.QXChatCommitRequest
			if common.Unmarshal(body, &input) != nil { w.WriteHeader(http.StatusBadRequest); return }
			if fixture.refuseCommit || input.CredentialVersion != fixture.profile.CredentialVersion || (fixture.committed != nil && *fixture.committed != input) {
				status, result = http.StatusConflict, map[string]string{"error": "credentials changed"}
			} else {
				fixture.committed = &input
				result = map[string]any{"request_id": input.RequestID, "source_id": input.SourceID, "newapi_user_id": input.NewAPIUserID, "authority": "newapi", "authority_version": input.AuthorityVersion}
				if fixture.loseReceipt { fixture.loseReceipt = false; status = http.StatusServiceUnavailable }
			}
		default:
			w.WriteHeader(http.StatusNotFound)
			return
		}
		encoded, err := common.Marshal(result)
		if !assert.NoError(t, err) { w.WriteHeader(http.StatusInternalServerError); return }
		responseDigest := sha256.Sum256(encoded)
		responseCanonical := strings.Join([]string{"qxchat-identity-response-v1", nonce, strconv.Itoa(status), hex.EncodeToString(responseDigest[:])}, "\n")
		signature := common.GenerateHMACWithKey([]byte(qxchatTestSecret), responseCanonical)
		if fixture.tamperResponse { signature = strings.Repeat("0", 64) }
		w.Header().Set("X-QXChat-Signature", signature)
		w.WriteHeader(status)
		_, _ = w.Write(encoded)
	}))
	t.Cleanup(server.Close)
	t.Setenv("QXCHAT_IDENTITY_ENABLED", "1")
	t.Setenv("QXCHAT_IDENTITY_SECRET", qxchatTestSecret)
	t.Setenv("QXCHAT_IDENTITY_SOURCE_URL", server.URL)
	return fixture
}

func TestQXChatPasswordCompatibility(t *testing.T) {
	for _, encoded := range []string{qxchatTestLegacyHash, qxchatTestCurrentHash} {
		hash, err := common.ImportQXChatPasswordHash(encoded)
		require.NoError(t, err)
		assert.True(t, common.ValidatePasswordAndHash(qxchatTestPassword, hash))
		assert.False(t, common.ValidatePasswordAndHash(qxchatTestPassword+"wrong", hash))
		assert.False(t, common.ValidatePasswordAndHash(strings.Repeat("😀", 65), hash))
		assert.False(t, common.ValidatePasswordAndHash(qxchatTestPassword, encoded))
	}
	for _, encoded := range []string{"", "$qxchat$" + qxchatTestLegacyHash, strings.Replace(qxchatTestCurrentHash, "131072", "1048576", 1), strings.Replace(qxchatTestCurrentHash, "$8$1$", "$8$2$", 1)} {
		_, err := common.ImportQXChatPasswordHash(encoded)
		assert.Error(t, err)
	}
	for _, algorithm := range []string{"bcrypt", "argon2id"} {
		t.Run(algorithm, func(t *testing.T) {
			t.Setenv("ACCOUNT_PASSWORD_HASH_ALGORITHM", algorithm)
			hash, err := common.HashAccountPassword(qxchatTestPassword)
			require.NoError(t, err)
			assert.True(t, common.ValidatePasswordAndHash(qxchatTestPassword, hash))
			assert.False(t, common.ValidatePasswordAndHash("wrong", hash))
		})
	}
}

func TestQXChatPendingImportIsDisabledAndIdempotent(t *testing.T) {
	setupQXChatIdentityTest(t)
	profile := qxchatTestProfile()
	mapping, user, err := model.PrepareQXChatIdentity(profile, nil)
	require.NoError(t, err)
	assert.Equal(t, model.QXChatUserPendingStatus, user.Status)
	assert.Equal(t, common.RoleCommonUser, user.Role)
	assert.Zero(t, user.Quota)
	assert.Zero(t, user.AffQuota)
	login := model.User{Username: user.Username, Password: qxchatTestPassword}
	assert.Error(t, login.ValidateAndFill())
	_, err = service.CreateLoginSession(user.Id, "qxchat", "127.0.0.1", "pending-test")
	assert.Error(t, err)
	profile.RequestID = "bbbbbbbb-cccc-4ddd-8eee-ffffffffffff"
	second, same, err := model.PrepareQXChatIdentity(profile, nil)
	require.NoError(t, err)
	assert.Equal(t, user.Id, same.Id)
	assert.Equal(t, mapping.RequestID, second.RequestID)
	require.NoError(t, model.MigrateQXChatIdentity(model.DB))
	_, err = model.ResolveQXChatIdentity(profile.SourceID)
	assert.ErrorIs(t, err, model.ErrQXChatIdentityInactive)
	var count int64
	require.NoError(t, model.DB.Model(&model.QXChatIdentity{}).Count(&count).Error)
	assert.EqualValues(t, 1, count)
}

func TestQXChatLostReceiptResumesAndNewPasswordIsAuthoritative(t *testing.T) {
	setupQXChatIdentityTest(t)
	source := startQXChatSourceFixture(t)
	source.loseReceipt = true
	_, err := service.LoginQXChatIdentity(context.Background(), "legacy-user", qxchatTestPassword)
	assert.ErrorIs(t, err, service.ErrQXChatUnavailable)
	first, err := model.FindQXChatIdentity("legacy-user")
	require.NoError(t, err)
	assert.Equal(t, model.QXChatIdentityPending, first.State)
	user, err := service.LoginQXChatIdentity(context.Background(), "legacy-user", qxchatTestPassword)
	require.NoError(t, err)
	assert.Equal(t, first.UserID, user.Id)
	assert.Equal(t, 1, source.prepareCalls)
	assert.Equal(t, 2, source.commitCalls)
	current, err := common.HashAccountPassword("newapi-authoritative-password")
	require.NoError(t, err)
	require.NoError(t, model.DB.Model(user).Update("password", current).Error)
	_, err = service.LoginQXChatIdentity(context.Background(), "legacy-user", qxchatTestPassword)
	assert.ErrorIs(t, err, model.ErrInvalidCredentials)
	_, err = service.LoginQXChatIdentity(context.Background(), "legacy@example.com", "newapi-authoritative-password")
	assert.NoError(t, err)
	assert.Equal(t, 1, source.prepareCalls)
	assert.Zero(t, user.Quota)
	assert.Equal(t, common.RoleCommonUser, user.Role)
	require.NoError(t, model.DB.Model(user).Update("status", common.UserStatusDisabled).Error)
	_, err = service.LoginQXChatIdentity(context.Background(), "legacy-user", "newapi-authoritative-password")
	assert.ErrorIs(t, err, model.ErrInvalidCredentials)
	require.NoError(t, model.DB.Delete(user).Error)
	_, err = model.ResolveQXChatIdentity(qxchatTestSource)
	assert.ErrorIs(t, err, model.ErrQXChatIdentityInactive)
	_, _, err = model.PrepareQXChatIdentity(qxchatTestProfile(), nil)
	assert.ErrorIs(t, err, model.ErrQXChatIdentityInactive)
}

func TestQXChatRejectsUntrustedResponseAndChangedCredentials(t *testing.T) {
	for _, scenario := range []string{"invalid signature", "commit refused"} {
		t.Run(scenario, func(t *testing.T) {
			setupQXChatIdentityTest(t)
			source := startQXChatSourceFixture(t)
			source.tamperResponse = scenario == "invalid signature"
			source.refuseCommit = scenario == "commit refused"
			_, err := service.LoginQXChatIdentity(context.Background(), "legacy-user", qxchatTestPassword)
			assert.Error(t, err)
			_, err = model.ResolveQXChatIdentity(qxchatTestSource)
			assert.ErrorIs(t, err, model.ErrQXChatIdentityInactive)
			var enabled int64
			require.NoError(t, model.DB.Model(&model.User{}).Where("username = ? AND status = ?", "legacy-user", common.UserStatusEnabled).Count(&enabled).Error)
			assert.Zero(t, enabled)
		})
	}
}

func TestQXChatCollisionRequiresBothAccountsAndProofCannotReplay(t *testing.T) {
	user, identity := setupQXChatIdentityTest(t)
	source := startQXChatSourceFixture(t)
	source.profile.Email = "same@example.com"
	require.NoError(t, model.DB.Model(user).Update("email", source.profile.Email).Error)
	_, err := service.LoginQXChatIdentity(context.Background(), "legacy-user", qxchatTestPassword)
	assert.ErrorIs(t, err, model.ErrQXChatIdentityConflict)
	assert.Zero(t, source.commitCalls)
	body, err := common.Marshal(map[string]string{"username": "legacy-user", "password": qxchatTestPassword})
	require.NoError(t, err)
	response := securityEnrollmentRequest("POST", "/api/user/qxchat/bind", string(body), "", identity, QXChatIdentityBind)
	assert.Equal(t, http.StatusForbidden, response.Code)
	assert.Zero(t, source.commitCalls)
	operation := service.VerificationOperation{Scope: service.VerificationScopeAccountBind, Context: []byte(`{"provider":"qxchat","code":"legacy-user"}`)}
	proof := issueSecurityEnrollmentProof(t, identity, operation, service.VerificationMethodPassword)
	response = securityEnrollmentRequest("POST", "/api/user/qxchat/bind", string(body), proof, identity, QXChatIdentityBind)
	var result securityEnrollmentResponse
	require.NoError(t, common.Unmarshal(response.Body.Bytes(), &result))
	require.True(t, result.Success, response.Body.String())
	stored, err := model.GetUserById(user.Id, true)
	require.NoError(t, err)
	assert.Equal(t, user.Password, stored.Password)
	assert.Equal(t, user.Role, stored.Role)
	assert.Equal(t, user.Quota, stored.Quota)
	mapping, err := model.ResolveQXChatIdentity(qxchatTestSource)
	require.NoError(t, err)
	assert.Equal(t, user.Id, mapping.UserID)
	response = securityEnrollmentRequest("POST", "/api/user/qxchat/bind", string(body), proof, identity, QXChatIdentityBind)
	assert.Equal(t, http.StatusForbidden, response.Code)
	_, err = service.LoginQXChatIdentity(context.Background(), "legacy-user", qxchatTestPassword)
	assert.ErrorIs(t, err, model.ErrInvalidCredentials)
	_, err = service.LoginQXChatIdentity(context.Background(), "legacy-user", "enrollment-password")
	assert.NoError(t, err)
}

func TestQXChatLoginPreservesMFA(t *testing.T) {
	user, _ := setupQXChatIdentityTest(t)
	startQXChatSourceFixture(t)
	require.NoError(t, model.DB.Create(&model.QXChatIdentity{SourceID: qxchatTestSource, UserID: user.Id, SourceUsername: "legacy-user", SourceEmail: "legacy@example.com", RequestID: qxchatTestRequest,
		CredentialVersion: strings.Repeat("a", 64), AuthorityVersion: 1, State: model.QXChatIdentityActive}).Error)
	require.NoError(t, model.DB.Create(&model.TwoFA{UserId: user.Id, Secret: "JBSWY3DPEHPK3PXP", IsEnabled: true}).Error)
	response := securityEnrollmentRequest("POST", "/api/user/login/qxchat", `{"username":"legacy-user","password":"enrollment-password"}`, "", service.AuthIdentity{}, QXChatIdentityLogin)
	var result struct { Success bool `json:"success"`; Data struct { RequiresVerification bool `json:"requires_verification"`; FlowToken string `json:"flow_token"`; AccessToken string `json:"access_token"` } `json:"data"` }
	require.NoError(t, common.Unmarshal(response.Body.Bytes(), &result))
	require.True(t, result.Success, response.Body.String())
	assert.NotEmpty(t, result.Data.FlowToken)
	assert.Empty(t, result.Data.AccessToken)
	assert.Empty(t, response.Header().Values("Set-Cookie"))
}
